import {startMarketRefresh} from './live-market.js?v=activity-fallback-2';
import {setupTabs} from './tabs.js?v=allocation-placement-1';
const $ = s => document.querySelector(s);
const compact = v => v == null ? '—' : Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(v);
const usd = v => v == null ? '—' : Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v);
const money = v => v == null ? '—' : '$'+compact(v);
const pct = v => v == null ? '—' : (v>0?'+':'')+v.toFixed(2)+'%';
const price = v => v == null ? '—' : '$' + v.toLocaleString('en-US',{minimumFractionDigits:6,maximumFractionDigits:6});
const bitcoin = v => v == null ? '₿—' : '₿'+v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:8});
const signedPrice = v => v == null ? '—' : (v>=0?'+':'-')+'$'+Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:6,maximumFractionDigits:6});
const signedMoney = v => v == null ? '—' : (v>=0?'+':'-')+'$'+compact(Math.abs(v));
const text = (selector,value) => {$(selector).textContent=value;};
const TEST_MINT='CbcyNo7m1amFWqEQm2m4PLv1UNvpcL3C1Ujm6AkzpKoU';
const simulation=new URLSearchParams(location.search).get('mode')==='test';
if(simulation){
 text('.dashboard-heading h1','e/acc · Test simulation');
 text('.primary-metric .token-code','Price');
 text('#performance h2','$e/acc Performance · Test');
 document.querySelectorAll('[data-link=buy]').forEach(el=>{el.disabled=true;el.textContent='Test mode';});
 text('#fee-note','Test mode: no holder-distribution history is supplied by this market-data feed.');
}
let lastMarket=null;
let config,token,distributions,range='30D',chartMode='price',chartPoints=[],hovered=-1,lastDistributionId=null,lastSender=null,polling=false;
const days={'15M':15/1440,'1H':1/24,'4H':4/24,'1D':1,'7D':7,'30D':30,'3M':90,'ALL':Infinity};
const labels={'15M':'Last 15 minutes','1H':'Last hour','4H':'Last 4 hours','1D':'Last 24 hours','7D':'Last 7 days','30D':'Last 30 days','3M':'Last 3 months','ALL':'All available history'};
let toastTimer;
function toast(message){text('#toast',message);$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function updateTokenAddress(){const address=simulation?TEST_MINT:config?.tokenAddress,button=$('#copy-token');text('#token-address',address||'CONTRACT PENDING');button.disabled=!address;button.title=address?'Copy token contract address':'Token contract pending';}
function navigate(url,fallback){if(url&&/^https:\/\//i.test(url))window.open(url,'_blank','noopener,noreferrer');else toast(fallback||'This link will be available when the official address is confirmed.');}
function metric(label,value,note='',change=null,highlight=false){const el=document.createElement('div');el.className='metric'+(highlight?' fee-highlight':'');const l=document.createElement('span');l.className='metric-label';l.textContent=label;const v=document.createElement('strong');v.textContent=value;const n=document.createElement('span');n.className='metric-note'+(change>0?' positive':change<0?' negative':'');n.textContent=note;el.append(l,v,n);return el;}
function currentChange(value,stored){if(value==null)return null;if(!(stored?.baseline>0))return stored||null;const amount=value-stored.baseline;return {amount,percent:amount/stored.baseline*100,baseline:stored.baseline};}
function setPrimaryChange(selector,change,fallback,priceAmount=false){const el=$(selector);el.textContent=change?`${priceAmount?signedPrice(change.amount):signedMoney(change.amount)} (${pct(change.percent)})`:(token?.status==='live'?'24H comparison collecting':fallback);el.className='metric-note'+(change?.percent>0?' positive':change?.percent<0?' negative':'');}
function updateTheme(){const light=document.documentElement.dataset.theme==='light';text('#theme-icon',light?'☾':'☀');document.getElementById("theme-toggle").title=light?'Switch to dark mode':'Switch to light mode';$('#theme-toggle').setAttribute('aria-label',light?'Switch to dark mode':'Switch to light mode');$('#theme-toggle').setAttribute('aria-pressed',String(light));document.querySelector('meta[name="theme-color"]').content=light?'#fafafa':'#050505';}
updateTheme();$('#theme-toggle').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('inu-theme',theme);}catch{}updateTheme();drawChart();});
updateTokenAddress();$('#copy-token').addEventListener('click',async()=>{const address=simulation?TEST_MINT:config?.tokenAddress;if(!address)return;try{await navigator.clipboard.writeText(address);toast('Token contract address copied.');}catch{toast('Copy unavailable. Select the address and copy it manually.');}});
document.querySelectorAll('[data-link]').forEach(el=>el.addEventListener('click',()=>navigate(config?.links?.[el.dataset.link],el.dataset.link==='buy'?'Token launching soon. The official buy link will appear after launch.':undefined)));
function closeMenu(){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','Open navigation');}
$('#menu').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Close navigation':'Open navigation');});
$('#navigation').addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();hovered=-1;$('#chart-tooltip').hidden=true;drawChart();}});
document.querySelectorAll('[data-range]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.range===range));b.addEventListener('click',()=>{range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});hovered=-1;$('#chart-tooltip').hidden=true;drawChart();});});
document.querySelectorAll('[data-chart-mode]').forEach(b=>b.addEventListener('click',()=>{chartMode=b.dataset.chartMode;document.querySelectorAll('[data-chart-mode]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});hovered=-1;$('#chart-tooltip').hidden=true;drawChart();}));
function renderToken(data){
 if(lastMarket)data={...data,...lastMarket};
 for(const key of ['price','priceChange24h','marketCap','liquidity','volume24h']){if(data[key]==null&&token?.[key]!=null)data[key]=token[key];}
 token=data;text('#holder-total',compact(data.holders));text('#holder-detail',data.holdersSource?'Source: '+data.holdersSource+' · '+new Date(data.holdersUpdatedAt).toLocaleString():'Holder data unavailable.');
 const holderRows=(data.topHolders||[]).map((row,index)=>{const tr=document.createElement('tr');const rank=document.createElement('td');rank.textContent=String(index+1);const wallet=document.createElement('td'),link=document.createElement('a');link.href='https://solscan.io/account/'+encodeURIComponent(row.address);link.target='_blank';link.rel='noopener noreferrer';link.textContent=row.address.slice(0,5)+'…'+row.address.slice(-5)+' ↗';wallet.append(link);const balance=document.createElement('td');balance.textContent=compact(row.amount);const share=document.createElement('td');share.textContent=row.percentage==null?'—':row.percentage.toFixed(2)+'%';tr.append(rank,wallet,balance,share);return tr;});
 if(!holderRows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.className='empty-row';td.textContent='Holder distribution is temporarily unavailable.';tr.append(td);holderRows.push(tr);}$('#holder-rows').replaceChildren(...holderRows);
 text('#price',price(data.price));text('#primary-cap',money(data.marketCap));text('#primary-liquidity',money(data.liquidity));text('#primary-volume',money(data.volume24h));
 const stored=data.metricChanges24h||{};let priceChange=currentChange(data.price,stored.price),capChange=currentChange(data.marketCap,stored.marketCap);
 if(data.price!=null&&data.priceChange24h!=null&&data.priceChange24h>-100){const baseline=data.price/(1+data.priceChange24h/100);priceChange={amount:data.price-baseline,percent:data.priceChange24h,baseline};if(data.marketCap!=null){const capBaseline=data.marketCap/(1+data.priceChange24h/100);capChange={amount:data.marketCap-capBaseline,percent:data.priceChange24h,baseline:capBaseline};}}
 setPrimaryChange('#price-change',priceChange,'Awaiting token launch',true);setPrimaryChange('#primary-cap-change',capChange,'USD market value');setPrimaryChange('#primary-liquidity-change',currentChange(data.liquidity,stored.liquidity),'Available pool liquidity');setPrimaryChange('#primary-volume-change',currentChange(data.volume24h,stored.volume24h),'Trading volume · USD');
 text('#data-status',data.status==='live'?'MARKET DATA':data.status==='error'?'DATA UNAVAILABLE':'TOKEN LAUNCHING SOON');$('#data-status').classList.toggle('live',data.status==='live');
 text('#data-caption',data.status==='live'?`As of ${new Date(data.updatedAt).toLocaleString()} · ${data.source}`:data.status==='error'?'Market data is temporarily unavailable. Waiting for the next verified update.':'Market data will appear after launch. Unavailable metrics are shown as —.');
 const buys=data.activity?.buys,sells=data.activity?.sells,trades=buys!=null&&sells!=null?buys+sells:null,d={...(data.metrics||{}),trades24h:trades??data.metrics?.trades24h,buySellRatio:sells>0&&buys!=null?buys/sells:data.metrics?.buySellRatio,averageTrade:trades>0&&data.volume24h!=null?data.volume24h/trades:data.metrics?.averageTrade,volumeLiquidityRatio:data.liquidity>0&&data.volume24h!=null?data.volume24h/data.liquidity:data.metrics?.volumeLiquidityRatio};
 const rows=[['Holders',compact(data.holders),data.holdersSource?'Holders · '+data.holdersSource:data.holdersStatus==='not-configured'?'Holder data not connected':'Holder data unavailable'],['24H Return',pct(data.priceChange24h),'Price change · 24 hours',data.priceChange24h],['7D Return',pct(data.return7d),'Price change · 7 days',data.return7d],['30D Return',pct(data.return30d),'Price change · 30 days',data.return30d],['Trades 24H',compact(d.trades24h),'Tracked trading pool'],['Buys 24H',compact(data.activity?.buys),'Tracked trading pool'],['Sells 24H',compact(data.activity?.sells),'Tracked trading pool'],['Buy / Sell Ratio',d.buySellRatio==null?'—':d.buySellRatio.toFixed(2)+'×','Trades · last 24 hours'],['Average Trade',money(d.averageTrade),'USD · tracked trading pool'],['Volume / Liquidity',d.volumeLiquidityRatio==null?'—':d.volumeLiquidityRatio.toFixed(2)+'×','24H volume / pool liquidity'],['Total Supply',compact(data.totalSupply),simulation?'e/acc test tokens':'INSTR tokens'],[config.distribution.displayLabel||'Fees Distributed to Holders',money(distributions?.totalUsdValue),'Lifetime · verified distributions',null,true]];
 if(simulation)rows.pop();
 $('#metrics').replaceChildren(...rows.map(x=>metric(...x)));drawChart();
}
function renderDistributions(data){
 distributions=data;text('#fee-title',config.distribution.displayLabel||'Fees Distributed to Holders');const sender=config.distribution.senderAddress,configured=Boolean(sender);
 text('#recipient',configured?`Distribution wallet · ${sender}`:'Awaiting distribution wallet configuration');text('#fee-status',data.status==='verified'?'VERIFIED ON SOLANA':data.status==='error'?'DATA UNAVAILABLE':configured?'VERIFICATION PENDING':'AWAITING DISTRIBUTION WALLET');
 text('#fee-total-btc',bitcoin(data.totalBtcValue));text('#fee-total',usd(data.totalUsdValue));text('#fee-count',data.transactionCount==null?'—':data.transactionCount.toLocaleString());text('#fee-last',data.lastDistribution?new Date(data.lastDistribution.timestamp).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—');text('#fee-day',usd(data.distributed24h));text('#distribution-asset',data.assetSymbol||'—');text('#fee-note',data.note||'Only finalized transfers from the configured distribution wallet are counted.');
 const receiverRows=(data.topReceivers||[]).map((receiver,index)=>{const tr=document.createElement('tr'),rank=document.createElement('td');rank.textContent=String(index+1);const wallet=document.createElement('td'),link=document.createElement('a');link.href='https://solscan.io/account/'+encodeURIComponent(receiver.address);link.target='_blank';link.rel='noopener noreferrer';link.textContent=receiver.address.slice(0,5)+'…'+receiver.address.slice(-5)+' ↗';wallet.append(link);tr.append(rank,wallet);for(const value of [receiver.amount.toLocaleString(undefined,{maximumFractionDigits:8})+' '+data.assetSymbol,receiver.usdValue==null?'Unpriced':usd(receiver.usdValue),receiver.percentage==null?'—':receiver.percentage.toFixed(2)+'%']){const td=document.createElement('td');td.textContent=value;tr.append(td);}return tr;});
 if(!receiverRows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.className='empty-row';td.textContent=data.status==='error'?'Distribution leaderboard is temporarily unavailable.':'No verified holder distributions yet.';tr.append(td);receiverRows.push(tr);}$('#receiver-rows').replaceChildren(...receiverRows);
 const rows=(data.transactions||[]).slice(0,10).map(tx=>{const tr=document.createElement('tr');const receiver=tx.recipient.slice(0,5)+'…'+tx.recipient.slice(-5);[new Date(tx.timestamp).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}),receiver,tx.amount.toLocaleString(undefined,{maximumFractionDigits:8})+' '+tx.asset,tx.usdValue==null?'Unpriced':usd(tx.usdValue)].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);});const td=document.createElement('td'),a=document.createElement('a');a.textContent=tx.txHash.slice(0,5)+'…'+tx.txHash.slice(-5)+' ↗';a.href='https://solscan.io/tx/'+encodeURIComponent(tx.txHash);a.target='_blank';a.rel='noopener noreferrer';td.append(a);tr.append(td);return tr;});
 if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.className='empty-row';td.textContent=data.status==='error'?'Distribution history is temporarily unavailable.':'No verified holder distributions yet.';tr.append(td);rows.push(tr);}$('#fee-rows').replaceChildren(...rows);
 text('#asset-totals',data.totalAmount==null?'':`Distributed on-chain · ${data.totalAmount.toLocaleString(undefined,{maximumFractionDigits:8})} ${data.assetSymbol}`);$('#view-fees').disabled=!configured;$('#view-fees').onclick=()=>navigate(config.distribution.explorerAddressUrl||'https://solscan.io/account/'+encodeURIComponent(sender));
 if(lastSender!==sender){lastSender=sender;lastDistributionId=null;}const nextId=data.lastDistribution?.txHash;if(lastDistributionId&&nextId&&lastDistributionId!==nextId){$('.fee-summary').classList.remove('fresh');requestAnimationFrame(()=>$('.fee-summary').classList.add('fresh'));}if(nextId)lastDistributionId=nextId;
}
function drawChart(){
 text('#chart-range',labels[range]);const all=token?.historyByRange?.[range]||token?.history||[],supply=token?.totalSupply>0?token.totalSupply:token?.marketCap>0&&token?.price>0?token.marketCap/token.price:null,valueOf=p=>chartMode==='marketCap'&&supply?p.price*supply:p.price,modeLabel=chartMode==='marketCap'?'Market cap':'Token price';$('#chart-mode-marketCap').disabled=!supply;text('#chart-measure-label',modeLabel);const cutoff=Date.now()-days[range]*86400000;chartPoints=all.filter(x=>x.timestamp>=cutoff&&Number.isFinite(valueOf(x)));const statRows=[['CURRENT PRICE',price(token?.price)],['MARKET CAP',money(token?.marketCap)],['24H VOLUME',money(token?.volume24h)],['LIQUIDITY',money(token?.liquidity)],['PERIOD CHANGE',chartPoints.length>1&&valueOf(chartPoints[0])>0?pct((valueOf(chartPoints.at(-1))/valueOf(chartPoints[0])-1)*100):'—']];if($('#performance-stats'))$('#performance-stats').replaceChildren(...statRows.map(([l,v])=>metric(l,v,l==='PERIOD CHANGE'?'Available plotted history':'')));const canvas=$('#price-chart'),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height;
 $('#chart-empty').hidden=chartPoints.length>0;text('#chart-source',all.length?modeLabel+' & volume · '+(token.historySource||token.source)+' · Available history · 5 min refresh':token?.status==='live'?'Historical chart data not yet available':'Awaiting market data');$('#chart').setAttribute('aria-label',chartPoints.length?`${labels[range]} token ${chartMode==='marketCap'?'market cap':'price'} chart. Use arrow keys to inspect ${chartPoints.length} observations.`:`No ${modeLabel.toLowerCase()} history available for ${labels[range].toLowerCase()}`);
 if(!chartPoints.length)return;const pad={left:6,right:77,top:14,bottom:27};const plotW=w-pad.left-pad.right,plotH=h-pad.top-pad.bottom-45;const low=Math.min(...chartPoints.map(valueOf)),high=Math.max(...chartPoints.map(valueOf));const span=high-low||high*.1||1;const min=low-span*.08,max=high+span*.08;const start=chartPoints[0].timestamp,end=chartPoints.at(-1).timestamp;
 const x=(p,i)=>pad.left+(end===start?.5:(p.timestamp-start)/(end-start))*plotW;const y=p=>pad.top+(max-valueOf(p))/(max-min)*plotH;
 ctx.beginPath();chartPoints.forEach((p,i)=>i?ctx.lineTo(x(p,i),y(p)):ctx.moveTo(x(p,i),y(p)));ctx.lineTo(x(chartPoints.at(-1),chartPoints.length-1),plotH+pad.top);ctx.lineTo(x(chartPoints[0],0),plotH+pad.top);ctx.closePath();const gradient=ctx.createLinearGradient(0,0,0,plotH);gradient.addColorStop(0,'#ed5a2b20');gradient.addColorStop(1,'#ed5a2b00');ctx.fillStyle=gradient;ctx.fill();ctx.beginPath();chartPoints.forEach((p,i)=>i?ctx.lineTo(x(p,i),y(p)):ctx.moveTo(x(p,i),y(p)));ctx.strokeStyle='#ed5a2b';ctx.lineWidth=2;ctx.stroke();if(chartPoints.length===1){ctx.beginPath();ctx.arc(x(chartPoints[0],0),y(chartPoints[0]),3,0,Math.PI*2);ctx.fillStyle='#ed5a2b';ctx.fill();}
 const maxVol=Math.max(...chartPoints.map(p=>p.volume||0),1);ctx.fillStyle='#d4dcda';chartPoints.forEach((p,i)=>ctx.fillRect(x(p,i)-1,h-pad.bottom-((p.volume||0)/maxVol*30),Math.max(2,plotW/chartPoints.length*.55),(p.volume||0)/maxVol*30));
 ctx.font='10px Arial';ctx.fillStyle='#7c8589';ctx.textAlign='left';for(let i=0;i<4;i++){const value=max-(max-min)*i/3;ctx.fillText(chartMode==='marketCap'?money(value):'$'+value.toPrecision(3),w-pad.right+12,pad.top+plotH*i/3+4);}ctx.textAlign='center';for(let i=0;i<Math.min(5,chartPoints.length);i++){const p=chartPoints[Math.round(i/(Math.min(5,chartPoints.length)-1||1)*(chartPoints.length-1))];ctx.fillText((days[range]<=1?new Date(p.timestamp).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}):new Date(p.timestamp).toLocaleDateString(undefined,{month:'short',day:'numeric'})),Math.max(27,Math.min(w-40,x(p))),h-6);}
 if(hovered>=0&&chartPoints[hovered]){const p=chartPoints[hovered];ctx.setLineDash([3,3]);ctx.strokeStyle='#9aa2a6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x(p),0);ctx.lineTo(x(p),h-pad.bottom);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#ed5a2b';ctx.beginPath();ctx.arc(x(p),y(p),4,0,Math.PI*2);ctx.fill();const tip=$('#chart-tooltip');tip.textContent=`${new Date(p.timestamp).toLocaleString()}\n${chartMode==='marketCap'?'Market cap  '+money(valueOf(p)):'Price  '+price(p.price)}\nVolume  ${usd(p.volume)}`;tip.hidden=false;tip.style.left=Math.max(0,Math.min(w-215,x(p)+12))+'px';tip.style.top='15px';}
}
$('#chart').addEventListener('pointermove',e=>{if(!chartPoints.length)return;const rect=$('#chart').getBoundingClientRect();const target=chartPoints[0].timestamp+Math.max(0,Math.min(1,(e.clientX-rect.left-6)/(rect.width-83)))*(chartPoints.at(-1).timestamp-chartPoints[0].timestamp);hovered=chartPoints.reduce((best,p,i)=>Math.abs(p.timestamp-target)<Math.abs(chartPoints[best].timestamp-target)?i:best,0);drawChart();});
$('#chart').addEventListener('pointerleave',()=>{hovered=-1;$('#chart-tooltip').hidden=true;drawChart();});$('#chart').addEventListener('keydown',e=>{if(!chartPoints.length||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();hovered=e.key==='Home'?0:e.key==='End'?chartPoints.length-1:Math.max(0,Math.min(chartPoints.length-1,hovered+(e.key==='ArrowRight'?1:-1)));drawChart();});

new ResizeObserver(()=>drawChart()).observe($('#chart'));text('#year',new Date().getFullYear());
setupTabs(()=>{hovered=-1;$('#chart-tooltip').hidden=true;drawChart();});
const periods=$('.periods');$('#performance').append(periods);
const stats=document.createElement('div');stats.id='performance-stats';stats.className='performance-stats';$('#performance').append(stats);
async function refresh(){if(polling||document.hidden)return;polling=true;try{
 const response=await fetch('./data/snapshot.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('Snapshot unavailable');const snapshot=await response.json();
 if(snapshot.schemaVersion!==1||!snapshot.config||!snapshot.token||!snapshot.distributions)throw new Error('Invalid snapshot');
 if(simulation){
 const testResponse=await fetch('./data/test-token.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});
 if(!testResponse.ok)throw new Error('Test snapshot unavailable');
 const test=await testResponse.json();
 if(test.mint!=='CbcyNo7m1amFWqEQm2m4PLv1UNvpcL3C1Ujm6AkzpKoU'||!test.token)throw new Error('Invalid test snapshot');
 snapshot.token=test.token;snapshot.generatedAt=test.generatedAt;
 const t=snapshot.token;const buys=t.activity?.buys,sells=t.activity?.sells;
 const trades=buys!=null&&sells!=null?buys+sells:null;
 t.metrics={trades24h:trades,buySellRatio:sells>0&&buys!=null?buys/sells:null,averageTrade:trades>0&&t.volume24h!=null?t.volume24h/trades:null,volumeLiquidityRatio:t.liquidity>0&&t.volume24h!=null?t.volume24h/t.liquidity:null};
 }
 config=snapshot.config;updateTokenAddress();const generatedAt=Date.parse(snapshot.generatedAt);const stale=!Number.isFinite(generatedAt)||Date.now()-generatedAt>20*60000;
 // Suppress old prices and distribution totals. Do not present a stale snapshot as live.
 if(stale&&snapshot.token.status!=='prelaunch'){snapshot.token.status='error';for(const key of ['price','marketCap','liquidity','volume24h','priceChange24h','return7d','return30d'])snapshot.token[key]=null;snapshot.token.metrics={};snapshot.token.activity={};snapshot.token.snapshotStale=true;}
 if(stale&&snapshot.distributions.status!=='pending'){snapshot.distributions={...snapshot.distributions,status:'error',totalAmount:null,totalUsdValue:null,totalBtcValue:null,transactionCount:null,uniqueRecipients:null,distributed24h:null,transactions:[],topReceivers:[],lastDistribution:null,note:'The published distribution snapshot is stale. Totals are hidden until the next verified update.'};}
 if(!simulation)renderDistributions(snapshot.distributions);else distributions=snapshot.distributions;renderToken(lastMarket?{...snapshot.token,...lastMarket}:snapshot.token);if(simulation){text('#data-status',(lastMarket||snapshot.token.status==='live')?'TEST DATA':'TEST DATA UNAVAILABLE');text('#chart-empty strong','Historical data unavailable');text('#chart-empty>span:last-child','This test feed does not include price history.');}
 }catch{if(!token)toast('Dashboard data is temporarily unavailable. Retrying automatically.');else{text('#data-status','DATA UNAVAILABLE');text('#data-caption','Could not refresh. Last published snapshot remains visible; check its timestamp.');}}finally{polling=false;}}
const updateMarket=startMarketRefresh(()=>simulation?TEST_MINT:config?.tokenAddress,data=>{lastMarket={...lastMarket,...data};if(token&&config){renderToken({...token,...lastMarket});if(simulation)text('#data-status','TEST DATA');}});
await refresh();if(!lastMarket)void updateMarket();setInterval(refresh,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
